  const screenshots = {
    mobile:["source-tab.png","library.png","library.png","vehicle-now-playing.png","aaos-quality.png","aaos-dsp.png"],
    aaos:["aaos-quality.png","library.png","aaos-media-center.png","aaos-now-playing.png","aaos-quality.png","aaos-dsp.png"]
  };
  const section = (h,p,shot) => '<section><h2>'+h+'</h2><p>'+p+'</p>'+(shot ? '<figure><img src="/apps/dreammusic/assets/screenshots/'+shot+'" alt="Dream Music Player AVD screen"><figcaption>Dream Music Player · AVD capture</figcaption></figure>' : '')+'</section>';
  function render(page, d) {
    if(page==="home") return '<section class="home-hero"><span class="eyebrow">ANDROID · AAOS · MUSIC</span><h1>'+d[0]+'</h1><section class="hero-summary"><h2>'+summary[lang].title+'</h2><ul>'+summary[lang].items.map(item=>'<li>'+item+'</li>').join('')+'</ul></section><div class="hero-actions"><a class="action primary" href="'+APP+'manual/?lang='+lang+'">'+ui[lang].manual+'</a></div></section><section class="home-grid"><a class="home-card device-card" href="'+APP+'manual/mobile/?lang='+lang+'"><span>📱</span><h2>'+ui[lang].mobile+'</h2></a><a class="home-card device-card" href="'+APP+'manual/aaos/?lang='+lang+'"><span>🚗</span><h2>'+ui[lang].aaos+'</h2></a></section><section class="policy-panel"><h2>'+ui[lang].privacy+'</h2><p>'+link("privacy/",ui[lang].privacy)+" · "+link("terms/",ui[lang].terms)+" · "+link("support/",ui[lang].support)+'</p></section>';
    if(page==="manual") return '<h1>'+d[0]+'</h1><p class="lead">'+d[1]+'</p><div class="cards"><a href="'+APP+'manual/mobile/?lang='+lang+'"><h2>📱 '+d[2]+'</h2><p>'+d[3]+'</p></a><a href="'+APP+'manual/aaos/?lang='+lang+'"><h2>🚗 '+d[4]+'</h2><p>'+d[5]+'</p></a></div>';
    const type = page === "mobile" ? "mobile" : "aaos", x = d;
    const shots = screenshots[type];
    return '<h1>'+x[0]+'</h1><p class="lead">'+x[1]+'</p><p class="capture-note">'+(type==="aaos" ? aaosCaptureNote[lang] : mobileCaptureNote[lang])+'</p>'+section(type==="aaos" ? vehicleSafety[lang][0] : x[2],type==="aaos" ? vehicleSafety[lang][1] : x[3],type==="aaos" ? null : shots[0])+(lang==="ko" ? section(installTransfer.ko[type][0],installTransfer.ko[type][1]) : '')+section(x[4],x[5],shots[1])+section(x[6],x[7],shots[2])+section(nowPlaying[lang][0],nowPlaying[lang][1],shots[3])+section(x[10],x[11],shots[4])+section(quality[lang][type][0],quality[lang][type][1],shots[5])+section(proFx[lang][0],proFx[lang][1],"dream-pro-fx.png")+(type==="aaos" ? section(vehicleDisplay[lang][0],vehicleDisplay[lang][1],"vehicle-fullscreen-vu.gif") : '')+'<p class="footer">'+link("manual/",ui[lang].back)+" · "+link("support/",ui[lang].support)+'</p>';
  }
  const page = document.body.dataset.page || "home", d = docs[lang][page] || docs.en[page];
  document.documentElement.lang = lang === "zh" ? "zh-CN" : lang;
  document.head.insertAdjacentHTML("beforeend",'<style>:root{color-scheme:dark}*{box-sizing:border-box}body{max-width:1080px;margin:0 auto;padding:80px 20px 56px;font:16px/1.75 system-ui,sans-serif;color:#f5f6f8;background:radial-gradient(circle at 12% 0,#443019 0,transparent 28rem),radial-gradient(circle at 90% 18%,#492810 0,transparent 24rem),linear-gradient(145deg,#0a0b0e,#17191d 52%,#08090b)}main{position:relative;overflow:hidden;background:linear-gradient(135deg,#20242aee,#121417f4);border:1px solid #4b4e52;border-radius:22px;padding:clamp(24px,5vw,56px);box-shadow:0 26px 70px #000a}main:before{content:"";position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,#ff8b1f,#ffcf4c,#ff8b1f)}h1{font-size:clamp(2.35rem,7vw,4.4rem);line-height:1.05;letter-spacing:-.045em;margin:0;color:#fff}h2{margin-top:2.4rem;border-top:1px solid #45484d;padding-top:1rem;color:#ffd46b}.lead{max-width:46rem;color:#c8cbd0;font-size:clamp(1rem,2vw,1.2rem)}a{color:#ffd05b}.locale{position:fixed;z-index:10;top:16px;right:16px;background:#1d2025eF;border:1px solid #62656a;border-radius:10px;padding:7px 10px;box-shadow:0 8px 28px #0008;color:#fff}.locale select{background:#1d2025;color:#fff;border:0;outline:0}.cards,.home-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:28px}.cards a,.home-card{display:block;padding:24px;border:1px solid #52565d;border-radius:16px;text-decoration:none;background:linear-gradient(145deg,#2a2e34,#17191e);color:#f5f6f8;transition:transform .18s,box-shadow .18s,border-color .18s}.cards a:hover,.home-card:hover{transform:translateY(-4px);border-color:#ffb23e;box-shadow:0 16px 35px #0008}.cards h2,.home-card h2{border:0;padding:0;margin:0 0 8px;color:#fff}.home-hero{padding:clamp(20px,4vw,38px) 0 12px}.eyebrow{display:inline-block;margin-bottom:14px;padding:4px 10px;border:1px solid #916b28;border-radius:999px;color:#ffcb5c;font-size:.78rem;font-weight:800;letter-spacing:.12em}.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}.action{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:0 18px;border:1px solid #656970;border-radius:10px;color:#fff;text-decoration:none;font-weight:750}.action.primary{border-color:#ffb83d;background:linear-gradient(135deg,#ff8a1d,#ffbd42);color:#1b1306;box-shadow:0 10px 28px #e67b1938}.device-card span{font-size:2rem}.device-card p{margin:4px 0 0;color:#c7cacf}.policy-panel{margin-top:38px;padding:4px 18px 18px;border:1px solid #494d53;border-radius:14px;background:#121418aa}.policy-panel h2{margin-top:1rem}.policy-panel p{margin-bottom:0}figure{margin:1.2rem 0 0;border:1px solid #4d5157;border-radius:12px;overflow:hidden;background:#111}figure img{display:block;width:100%;height:auto}figcaption{padding:8px 12px;color:#dce4ec;font-size:.8rem}.footer{margin-top:2rem}@media(max-width:600px){body{padding:68px 10px 30px}main{border-radius:14px}.cards,.home-grid{grid-template-columns:1fr}h1{font-size:2.55rem}}</style>');
