  document.head.insertAdjacentHTML("beforeend",'<style>.capture-note{margin:.9rem 0 0;padding:.7rem .85rem;border-left:3px solid #ffb23e;border-radius:0 8px 8px 0;background:#17130bdd;color:#e5d7b8;font-size:.88rem;line-height:1.55}</style>');
  document.body.innerHTML = '<label class="locale"><span aria-hidden="true">🌐 </span><select id="locale" aria-label="Language">'+Object.entries(langs).map(([k,v])=>'<option value="'+k+'" '+(k===lang?"selected":"")+'>'+v+'</option>').join("")+'</select></label><main>'+render(page,d)+'</main>';
  document.getElementById("locale").addEventListener("change",e=>{localStorage.setItem("dreammusic-language",e.target.value);const u=new URL(location.href);u.searchParams.set("lang",e.target.value);location.href=u;});
